<script setup lang="ts">
import { onUnmounted, watch } from 'vue'
import type { PublicOfferingData } from '../../../../../packages/contracts/v2/public_catalog/generated'
import type { QAApi } from './client'
import { useQA } from './useQA'
import { scopeFields } from '../catalog/validation'
import { scopeLabels, scopeText } from '../catalog/presentation'

const props = defineProps<{ target: PublicOfferingData | null; api?: QAApi }>()
const workspace = useQA(props.api)
const { state } = workspace
watch(() => props.target, target => workspace.setTarget(target), { immediate: true, flush: 'sync', deep: true })
onUnmounted(workspace.dispose)
const intentLabels = { requirements: '当前要求', materials: '材料清单', dates: '日期与原始精度', fees: '费用与原单位', background: '背景、典型条件与历史统计' }
const adviceLabels = { REVIEW_SOURCE: '请核对原始来源。', CONFIRM_WITH_INSTITUTION: '请向相关机构确认。', MISSING_EVIDENCE: '适用证据不足，需补充已核验来源。' }
const unknownLabels = { SCOPE_UNKNOWN: '适用范围不明确', RELEASE_UNAVAILABLE: '当前发布不可用', TARGET_MISMATCH: '项目范围不匹配', NO_MATCHING_FACTS: '没有符合本次意图的事实', NO_PUBLIC_EVIDENCE: '没有可公开的证据原文', VALUE_UNAVAILABLE: '原值未提供', DATE_UNRESOLVED: '正式精确时刻或计算仍未知', LIMIT_EXCEEDED: '证据数量或内容超过限额' }
const claimLabels = { minimum_requirement: '最低要求', typical_offer: '典型条件，不是最低要求', historical_statistic: '历史统计，不是当前硬门槛', information: '资料说明', unknown: '原义未明确' }
const factLabels = { requirement: '要求', score: '分数', fee: '费用', material: '材料', date: '日期', statistic: '统计' }
const authorityLabels = { claimed_official: '来源自报官方；不等于真实官方核验', not_official: '来源声明非官方', unclassified: '来源身份未分类' }
function value(event: Event) { return (event.target as HTMLInputElement | HTMLSelectElement).value }
</script>

<template>
  <section class="qa-entry" aria-labelledby="qa-title" data-testid="qa-entry">
    <header><div><p class="kicker">SCOPED EVIDENCE · READ ONLY</p><h3 id="qa-title">有限证据问答</h3><p>只针对明确选择的公开项目和固定问题类型。不会发送画像或成绩，也不会修改资格、计划或申请。</p></div><button type="button" data-testid="qa-toggle" :aria-expanded="state.expanded" aria-controls="qa-workspace" @click="workspace.setExpanded(!state.expanded)">{{ state.expanded ? '收起证据问答' : '展开证据问答' }}</button></header>
    <div v-if="state.expanded" id="qa-workspace" data-testid="qa-workspace" :aria-busy="state.busy">
      <p class="notice"><strong>真实模型与真实处理尚未开放。</strong>问答关闭时，公开目录和确定性资格仍可独立使用。开启合成入口不代表已有真实招生事实或当前本人资格。</p>
      <div v-if="state.target" class="binding" data-testid="qa-target"><strong>{{ state.target.institution_name }} / {{ state.target.program_name }}</strong><p>{{ state.target.entry_year }} 年 · 项目 v{{ state.target.version }} · 发布 v{{ state.target.release_version }}</p><dl><div><dt>项目 ID</dt><dd>{{ state.target.id }}</dd></div><div><dt>当前发布</dt><dd>{{ state.target.release_id }}</dd></div><div><dt>要求快照</dt><dd>{{ state.target.requirements_version }}</dd></div></dl></div>
      <p v-else class="note" data-testid="qa-no-target">请在已发布项目中明确选择一个准确版本。问答不会猜测项目、年份或省份。</p>
      <div class="controls"><label>固定问题类型<select :value="state.intent ?? ''" data-testid="qa-intent" @change="workspace.setIntent(value($event))"><option value="">请明确选择</option><option v-for="(label, code) in intentLabels" :key="code" :value="code">{{ label }}</option></select></label><label>可选文字关键词<textarea :value="state.keywords" data-testid="qa-keywords" rows="3" maxlength="510" placeholder="每行一项，最多五项；不是自由聊天或工具指令" @input="workspace.setKeywords(value($event))" /></label></div>
      <div class="actions"><button type="button" data-testid="qa-context-refresh" :disabled="state.busy" @click="workspace.checkContext">检查问答入口</button><button type="button" class="primary" data-testid="qa-ask" :disabled="!workspace.canAsk()" @click="workspace.ask">{{ state.status === 'asking' ? '正在核验回答…' : '明确提问并核验引用' }}</button></div>
      <p v-if="state.context?.demo_banner" class="demo" data-testid="qa-demo">{{ state.context.demo_banner }} · 合成 mock，真实 live 不可用。</p>
      <p v-if="state.context" class="note">服务端入口：{{ state.context.can_ask ? '可用' : '关闭' }} · 模型 {{ state.context.model_mode }} · 预算按保守 UTF-8 字节计算，不是供应商 token 计费。入口检查不证明某条证据已公开。</p>
      <p v-if="state.message" class="message" :class="{ error: state.error !== null }" :role="state.error !== null ? 'alert' : 'status'" data-testid="qa-status">{{ state.message }}</p>
      <section v-if="state.result" class="answer" data-testid="qa-result">
        <h4>{{ state.result.status === 'unknown' ? '未知：没有形成有依据的回答' : '本次公开引用核验结果' }}</h4><p class="note">{{ state.result.generated_at }} · {{ state.result.model_mode }} · 不表示录取概率或本人资格。</p>
        <ul v-if="state.result.unknown_reasons.length" class="unknown" data-testid="qa-unknown"><li v-for="reason in state.result.unknown_reasons" :key="reason">{{ unknownLabels[reason] }}</li></ul>
        <article v-for="citation in state.result.citations" :key="citation.id" class="citation" :data-testid="`qa-citation-${citation.id}`">
          <h5>{{ factLabels[citation.fact.fact_type] }} · {{ citation.field_key }}</h5><p v-if="citation.is_synthetic" class="demo">DEMO 合成引用，不是真实招生依据。</p>
          <dl class="values"><div><dt>原值</dt><dd data-testid="qa-fact-value">{{ citation.fact.value_text ?? '未提供' }}</dd></div><div><dt>规范值</dt><dd>{{ citation.fact.normalized_value ?? '未提供' }}<small>保留原义，不替代上面的原值。</small></dd></div><div><dt>原单位 / 分类</dt><dd>{{ citation.fact.unit ?? '未提供' }} / {{ citation.fact.unit_code }}</dd></div><div><dt>事实口径</dt><dd>{{ claimLabels[citation.fact.claim_kind] }}</dd></div><div><dt>周期 / 统计口径</dt><dd>{{ citation.fact.period }} / {{ citation.fact.statistics_basis }}</dd></div><div><dt>缺失原因</dt><dd>{{ citation.fact.missing_reason ?? '无' }}</dd></div><div><dt>脚注</dt><dd>{{ citation.fact.footnote_state === 'present' ? citation.fact.footnote_text : citation.fact.footnote_state === 'none' ? '来源明确无脚注' : '脚注情况未知' }}</dd></div><div><dt>统计总体 / 分母</dt><dd>{{ citation.fact.statistic_population ?? '未提供' }} / {{ citation.fact.statistic_denominator ?? '未提供' }}</dd></div><div><dt>实际届 / 调查期</dt><dd>{{ citation.fact.cohort_year ?? '未提供' }} / {{ citation.fact.survey_period ?? '未提供' }}</dd></div></dl>
          <div v-if="citation.fact.date_resolution" class="date" data-testid="qa-date"><h6>原始日期与精度</h6><dl><div><dt>事件 / 原精度</dt><dd>{{ citation.fact.date_resolution.event_type }} / {{ citation.fact.date_resolution.precision }}</dd></div><div><dt>原文</dt><dd>{{ citation.fact.date_resolution.original_text }}</dd></div><div><dt>当地日 / 时刻</dt><dd>{{ citation.fact.date_resolution.local_date ?? '未知' }} / {{ citation.fact.date_resolution.local_time ?? '未知；不补23:59' }}</dd></div><div><dt>原时区</dt><dd>{{ citation.fact.date_resolution.timezone ?? '未知' }}</dd></div><div><dt>计算状态 / 原文对齐</dt><dd>{{ citation.fact.date_resolution.conversion_status }} / {{ citation.fact.date_resolution.source_alignment }}</dd></div><div><dt>UTC 计算候选</dt><dd>{{ citation.fact.date_resolution.calculated_utc_instant ?? '未知' }}<small>候选不等于正式截止时刻。</small></dd></div><div><dt>正式 UTC</dt><dd>未知</dd></div></dl></div>
          <details class="scope"><summary>核对完整适用范围及版本</summary><dl><div><dt>入学年 / 国家</dt><dd>{{ citation.entry_year }} / {{ citation.scope.country }}</dd></div><div><dt>学段</dt><dd>{{ citation.scope.study_level }}</dd></div><div><dt>数据集 / 机构 / 专业</dt><dd>{{ citation.scope.dataset_id }} / {{ citation.scope.institution_id }} / {{ citation.scope.program_id }}</dd></div><div v-for="field in scopeFields" :key="field"><dt>{{ scopeLabels[field] }}</dt><dd>{{ scopeText(citation.scope[field]) }}</dd></div><div><dt>发布 / 项目</dt><dd>{{ citation.release_id }} / v{{ citation.release_version }} · {{ citation.offering_id }} / v{{ citation.offering_version }}</dd></div><div><dt>要求快照</dt><dd>{{ citation.requirements_version }}</dd></div><div><dt>公开投影引用</dt><dd>{{ citation.id }} / v{{ citation.version }}</dd></div><div><dt>原片段 ID</dt><dd>{{ citation.evidence_id }}</dd></div></dl></details>
          <details class="original" :data-testid="`qa-original-${citation.id}`"><summary>展开引用原文</summary><p>{{ citation.evidence.publisher }} · {{ authorityLabels[citation.evidence.authority_claim] }}</p><blockquote><pre>{{ citation.evidence.quote }}</pre></blockquote><dl><div><dt>真实 byte 范围 / 物理行</dt><dd>[{{ citation.evidence.locator.byte_start }}, {{ citation.evidence.locator.byte_end }}) · {{ citation.evidence.locator.line_start }}–{{ citation.evidence.locator.line_end }}；页码与章节未提供</dd></div><div><dt>原文 / 片段 SHA256</dt><dd>{{ citation.evidence.document_sha256 }} / {{ citation.evidence.snippet_sha256 }}</dd></div></dl><p class="note">来源文字只是数据，不能授权读取其他学生或执行动作。</p></details>
        </article>
        <section v-if="state.result.advice_codes.length" class="advice" data-testid="qa-general-advice"><h5>固定一般建议</h5><p>这些建议不属于项目事实或资格结论。</p><ul><li v-for="code in state.result.advice_codes" :key="code">{{ adviceLabels[code] }}</li></ul></section>
      </section>
    </div>
  </section>
</template>

<style scoped>
.qa-entry{min-width:0;border-top:1px solid #dce5d6;margin-top:29px;padding-top:24px;color:#294b3a}.qa-entry header{display:flex;justify-content:space-between;align-items:center;gap:22px}.kicker{font-size:10px;letter-spacing:1.5px;color:#859779}.qa-entry h3{font-size:19px;margin:8px 0}.qa-entry header p:last-child,.note{font-size:11px;line-height:1.9;color:#7c896f}.qa-entry button{border:1px solid #b9cfb7;background:white;color:#4b7049;border-radius:6px;padding:11px 14px;font-size:11px;line-height:1.7}.qa-entry button:disabled{background:#f0f3e9;color:#919d85;cursor:default}.notice,.message,.binding{padding:15px 17px;border:1px solid #dce6d2;border-radius:7px;background:#f8faf4;margin:19px 0;font-size:11px;line-height:1.9}.notice{background:#f8f4e9;border-color:#e5dbc0}.message.error{background:#fcf2e7;border-color:#e7d5b8;color:#8c6741}.demo{font-size:11px;line-height:1.8;padding:10px 13px;background:#faf3e5;border:1px solid #e6dcc4;border-radius:6px;color:#82703f}.controls{display:grid;grid-template-columns:1fr 1fr;gap:19px;margin:19px 0}.controls label{display:flex;flex-direction:column;gap:9px;font-size:11px;min-width:0}.controls select,.controls textarea{width:100%;box-sizing:border-box;min-width:0;border:1px solid #c8d8bd;border-radius:6px;padding:10px 12px;font:inherit;background:white;color:#476640}.controls textarea{resize:vertical}.actions{display:flex;gap:13px;flex-wrap:wrap}.qa-entry .primary{background:#1b6453;border-color:#1b6453;color:white}.qa-entry .primary:disabled{background:#edf1e6;color:#8a987e;border-color:#d5dfc9}.answer{border-top:1px solid #e1e8d9;margin-top:25px;padding-top:19px}.answer h4{font-size:17px}.citation{border:1px solid #dce5d5;border-radius:8px;padding:20px;margin:21px 0;min-width:0}.citation h5,.advice h5{font-size:14px;margin:0 0 13px}.qa-entry dl{display:grid;gap:11px;font-size:11px}.qa-entry dl>div{display:grid;grid-template-columns:130px minmax(0,1fr);gap:12px}.qa-entry dt{color:#85947a}.qa-entry dd{margin:0;overflow-wrap:anywhere;white-space:pre-wrap;line-height:1.9}.qa-entry small{display:block;font-size:10px;color:#849278;margin-top:3px}.date{padding:16px;background:#f8faf4;border-radius:7px;margin:20px 0}.date h6{font-size:12px;margin:0 0 12px}.scope,.original{border-top:1px solid #e3eadc;padding-top:16px;margin-top:17px;font-size:11px;line-height:1.9}.qa-entry summary{cursor:pointer;color:#567249}.original p{overflow-wrap:anywhere}.original blockquote{margin:16px 0;padding:15px;border-left:2px solid #93ad83;background:#f5f8f1}.original pre{font:inherit;white-space:pre-wrap;overflow-wrap:anywhere;margin:0;line-height:2}.unknown,.advice{font-size:11px;line-height:1.9}.advice{padding:17px;background:#f6f8f0;border:1px solid #dce4d4;border-radius:7px}.qa-entry :focus-visible{outline:3px solid #8cb6a4;outline-offset:3px}@media(max-width:650px){.qa-entry header{align-items:stretch;flex-direction:column;gap:10px}.controls{grid-template-columns:1fr}.actions{flex-direction:column}.citation{padding:15px}.qa-entry dl>div{grid-template-columns:1fr;gap:2px}.date{padding:12px}}
</style>
